(function(g){'use strict';
 function rng(s){return()=>{s=(Math.imul(1664525,s)+1013904223)>>>0;return s/4294967296;};}
 const mean=a=>a.reduce((s,v)=>s+v,0)/a.length;
 function wells(seed,n,noise){let r=rng(seed),rows=[];for(let w=0;w<n;w++){let facies=r();for(let j=0;j<16;j++){let phi=.08+.19*r(),shale=.08+.42*r(),ai=11.5-14*phi+2.7*shale+(r()-.5)*noise,ratio=1.68+1.0*shale+.15*phi+(r()-.5)*noise*.07;rows.push({well:'W'+(seed+w),depth:2200+j*8,attributes:[ai,ratio],phi:phi*100,shale:shale*100});}}return rows;}
 function solve(a,b){a=a.map((r,i)=>r.slice().concat(b[i]));for(let i=0;i<b.length;i++){let p=i;for(let k=i+1;k<b.length;k++)if(Math.abs(a[k][i])>Math.abs(a[p][i]))p=k;[a[i],a[p]]=[a[p],a[i]];let z=a[i][i];if(Math.abs(z)<1e-12)throw Error('病态矩阵');for(let j=i;j<=b.length;j++)a[i][j]/=z;for(let k=0;k<b.length;k++)if(k!==i){let t=a[k][i];for(let j=i;j<=b.length;j++)a[k][j]-=t*a[i][j];}}return a.map(r=>r[b.length]);}
 function fit(train,lambda,dimensions){let mu=Array.from({length:dimensions},(_,j)=>mean(train.map(r=>r.attributes[j]))),sd=mu.map((v,j)=>Math.sqrt(mean(train.map(r=>(r.attributes[j]-v)**2)))||1),x=train.map(r=>[1,...mu.map((m,j)=>(r.attributes[j]-m)/sd[j])]),a=Array.from({length:dimensions+1},(_,i)=>Array.from({length:dimensions+1},(_,j)=>x.reduce((s,r)=>s+r[i]*r[j],0)+(i===j&&i>0?lambda:0))),b=Array.from({length:dimensions+1},(_,j)=>x.reduce((s,r,i)=>s+r[j]*train[i].phi,0));return{mu,sd,beta:solve(a,b)};}
 function predict(model,attributes){return attributes.map(row=>model.beta[0]+model.mu.reduce((s,m,j)=>s+model.beta[j+1]*(row[j]-m)/model.sd[j],0));}
 function metrics(pred,y){let errors=pred.map((p,i)=>p-y[i]),m=mean(y),sse=errors.reduce((s,v)=>s+v*v,0),sst=y.reduce((s,v)=>s+(v-m)**2,0);return{mae:mean(errors.map(Math.abs)),rmse:Math.sqrt(sse/y.length),r2:1-sse/sst,n:y.length};}
 function run(options){let noise=Number(options.noise),lambda=Number(options.lambda),train=wells(2101,8,.22),test=wells(7101,4,noise),multi=fit(train,lambda,2),single=fit(train,lambda,1),predictions=predict(multi,test.map(r=>r.attributes)),baseline=predict(single,test.map(r=>r.attributes));return{options:{noise,lambda},train,test,predictions,baseline,model:multi,metrics:metrics(predictions,test.map(r=>r.phi)),baseMetrics:metrics(baseline,test.map(r=>r.phi)),protocol:{trainWells:8,testWells:4,train:128,test:64,trainingSeed:2101,testSeed:7101,truthUsedOnlyForEvaluation:true}};}
 g.S17Case={run,fit,predict,metrics};
})(window);

